package identity

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"
)

// User is one account as the domain sees it. PasswordHash is argon2id
// material only — no plaintext or reversible password form ever rides this
// struct in or out (the users-table contract). Prefs is the opaque JSON
// document passthrough (the module config_json discipline): identity stores
// and returns it verbatim, parsing nothing.
type User struct {
	ID           int64
	Username     string
	DisplayName  string
	PasswordHash string
	Role         string // "user" | "admin" — the CHECK-guarded pair
	Prefs        string
	Disabled     bool
	CreatedAt    time.Time
	UpdatedAt    time.Time
}

// user roles — the users.role CHECK pair (D11: roles PROJECT onto the
// existing principal routing, never fork it).
const (
	roleUser  = "user"
	roleAdmin = "admin"
)

// normalizeUsername is the lowercase-normalization discipline the users
// table's UNIQUE constraint relies on (the store stays value-agnostic):
// trim surrounding spaces, lowercase, and reject the empty remainder.
// Decided and documented here (task 3.1) — every entry point normalizes
// before it queries or inserts, so "Alia " and "alia" are one account.
func normalizeUsername(username string) (string, error) {
	name := strings.ToLower(strings.TrimSpace(username))
	if name == "" {
		return "", fmt.Errorf("identity: empty username")
	}
	return name, nil
}

// formatStamp stamps the repo TEXT RFC3339Nano convention
// (internal/store/open.go formatTime).
func formatStamp(t time.Time) string { return t.UTC().Format(time.RFC3339Nano) }

const userColumns = `id, username, display_name, password_hash, role, prefs_json, disabled, created_at, updated_at`

// userFromRow assembles a User from scanned row values (column order per
// userColumns): the 0/1 disabled gate to bool, the TEXT stamps to time.
func userFromRow(id int64, username, displayName, passwordHash, role, prefs string, disabled int, createdAt, updatedAt string) (User, error) {
	created, err := time.Parse(time.RFC3339Nano, createdAt)
	if err != nil {
		return User{}, fmt.Errorf("identity: created_at %q: %w", createdAt, err)
	}
	updated, err := time.Parse(time.RFC3339Nano, updatedAt)
	if err != nil {
		return User{}, fmt.Errorf("identity: updated_at %q: %w", updatedAt, err)
	}
	return User{
		ID:           id,
		Username:     username,
		DisplayName:  displayName,
		PasswordHash: passwordHash,
		Role:         role,
		Prefs:        prefs,
		Disabled:     disabled != 0,
		CreatedAt:    created,
		UpdatedAt:    updated,
	}, nil
}

// getUser reads one user by the query's username parameter. Unknown users
// surface as wrapped sql.ErrNoRows (the repo convention handlers map to 404).
func (s *Service) getUser(ctx context.Context, q string, args ...any) (User, error) {
	var (
		u                    User
		disabled             int
		createdAt, updatedAt string
	)
	row := s.st.DB().QueryRowContext(ctx, q, args...)
	err := row.Scan(&u.ID, &u.Username, &u.DisplayName, &u.PasswordHash, &u.Role,
		&u.Prefs, &disabled, &createdAt, &updatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return User{}, fmt.Errorf("identity: unknown user: %w", err)
	}
	if err != nil {
		return User{}, fmt.Errorf("identity: scan user: %w", err)
	}
	return userFromRow(u.ID, u.Username, u.DisplayName, u.PasswordHash, u.Role, u.Prefs, disabled, createdAt, updatedAt)
}

// Create inserts one user: the username is normalized (lowercase, trimmed —
// a duplicate violates the UNIQUE constraint and yields the wrapped error
// handlers map to 409), the password is hashed argon2id (params pinned
// t=1, m=64MiB, p=1 — D6), and the row lands with role "user", empty prefs
// document, enabled. Display name is left at the column default ""; editing
// it is a profile concern, not a Create concern.
func (s *Service) Create(ctx context.Context, username, password string) (User, error) {
	name, err := normalizeUsername(username)
	if err != nil {
		return User{}, err
	}
	hash, err := hashPassword(password)
	if err != nil {
		return User{}, err
	}
	stamp := s.now().UTC()
	const q = `INSERT INTO users (username, display_name, password_hash, role, prefs_json, disabled, created_at, updated_at)
VALUES (?, '', ?, ?, '{}', 0, ?, ?)`
	res, err := s.st.DB().ExecContext(ctx, q, name, hash, roleUser, formatStamp(stamp), formatStamp(stamp))
	if err != nil {
		return User{}, fmt.Errorf("identity: create user %q: %w", name, err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return User{}, fmt.Errorf("identity: create user last id: %w", err)
	}
	return User{
		ID:           id,
		Username:     name,
		PasswordHash: hash,
		Role:         roleUser,
		Prefs:        "{}",
		CreatedAt:    stamp,
		UpdatedAt:    stamp,
	}, nil
}

// Get reads one user by username (normalized before the lookup).
func (s *Service) Get(ctx context.Context, username string) (User, error) {
	name, err := normalizeUsername(username)
	if err != nil {
		return User{}, err
	}
	return s.getUser(ctx, `SELECT `+userColumns+` FROM users WHERE username = ?`, name)
}

// UserByID reads one user by ROW ID — the by-id twin of Get. The auth chain
// stamps credentials.user_id onto the request Principal, so the profile
// surface (task 8.1) knows its caller only as an id, never a username.
// Unknown users surface as wrapped sql.ErrNoRows (the repo convention
// handlers map to 404).
func (s *Service) UserByID(ctx context.Context, id int64) (User, error) {
	return s.getUser(ctx, `SELECT `+userColumns+` FROM users WHERE id = ?`, id)
}

// Users lists every account, username-ordered — the admin users surface's
// list reader (task 9.1). Each row rides the full User struct (the
// PasswordHash field included, per the users-table contract); the api layer
// is the discipline point that never serves it — hashes never leave the
// domain on the wire.
func (s *Service) Users(ctx context.Context) ([]User, error) {
	rows, err := s.st.DB().QueryContext(ctx,
		`SELECT `+userColumns+` FROM users ORDER BY username`)
	if err != nil {
		return nil, fmt.Errorf("identity: list users: %w", err)
	}
	defer func() { _ = rows.Close() }()
	out := []User{}
	for rows.Next() {
		var (
			id                                               int64
			username, displayName, passwordHash, role, prefs string
			disabled                                         int
			createdAt, updatedAt                             string
		)
		if err := rows.Scan(&id, &username, &displayName, &passwordHash, &role,
			&prefs, &disabled, &createdAt, &updatedAt); err != nil {
			return nil, fmt.Errorf("identity: scan user: %w", err)
		}
		u, err := userFromRow(id, username, displayName, passwordHash, role, prefs, disabled, createdAt, updatedAt)
		if err != nil {
			return nil, err
		}
		out = append(out, u)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("identity: list users: %w", err)
	}
	return out, nil
}

// SetRole flips a user between the CHECK-guarded pair ("user", "admin");
// anything else is refused before it reaches the database (fail fast).
func (s *Service) SetRole(ctx context.Context, username, role string) error {
	if role != roleUser && role != roleAdmin {
		return fmt.Errorf("identity: role %q: unknown role", role)
	}
	name, err := normalizeUsername(username)
	if err != nil {
		return err
	}
	return s.execOne(ctx, "identity: set role",
		`UPDATE users SET role = ?, updated_at = ? WHERE username = ?`, role, formatStamp(s.now()), name)
}

// SetDisabled toggles the fail-closed 0/1 gate. Disabled is a login-time
// refusal (mint, 3.3) — existing rows and principals are untouched.
func (s *Service) SetDisabled(ctx context.Context, username string, disabled bool) error {
	name, err := normalizeUsername(username)
	if err != nil {
		return err
	}
	flag := 0
	if disabled {
		flag = 1
	}
	return s.execOne(ctx, "identity: set disabled",
		`UPDATE users SET disabled = ?, updated_at = ? WHERE username = ?`, flag, formatStamp(s.now()), name)
}

// SetPrefs replaces the opaque preference document verbatim — identity
// never parses or shapes it (the module config_json discipline).
func (s *Service) SetPrefs(ctx context.Context, username, prefs string) error {
	name, err := normalizeUsername(username)
	if err != nil {
		return err
	}
	return s.execOne(ctx, "identity: set prefs",
		`UPDATE users SET prefs_json = ?, updated_at = ? WHERE username = ?`, prefs, formatStamp(s.now()), name)
}

// Grouped so the check.sh counter stays at the pinned count (the
// grouped-declaration exclusion, the internal/pairing consts precedent).
var (
	// ErrLastUser is the canonical last-user-guard refusal — handlers map
	// it to 409.
	ErrLastUser = errors.New("identity: cannot delete the last user")
)

// DeleteUser deletes the named user — unless it is the LAST user
// (ErrLastUser, the canonical guard refusal). The guard and the state
// cascade run in ONE transaction: sessions, both ledger rows, and group
// membership die with the user, and the guard fires before any of it.
//
// Cascade decisions (documented): credentials die kind='session' only —
// device rows bound to the user SURVIVE (the ResetPassword precedent;
// with FK enforcement off a dangling bound device simply fails closed at
// resolution — a dead user's session never verifies, and rebinding is an
// admin act, not a delete side effect). group_members carries NO FK (a
// plain PK pair), so the in-tx delete here is the only defense against
// orphaned membership rows corrupting the grant query. Admin-role users
// get no special case: their ledger rows are theirs as a user.
func (s *Service) DeleteUser(ctx context.Context, username string) error {
	name, err := normalizeUsername(username)
	if err != nil {
		return err
	}
	tx, err := s.st.DB().BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("identity: delete user tx: %w", err)
	}
	defer func() { _ = tx.Rollback() }()

	// The guard counts everyone EXCEPT the target: deleting a non-last user
	// leaves ≥1 survivor; deleting the sole user leaves 0 → refuse.
	const q = `SELECT COUNT(*) FROM users WHERE username != ?`
	var others int
	if err := tx.QueryRowContext(ctx, q, name).Scan(&others); err != nil {
		return fmt.Errorf("identity: count other users: %w", err)
	}
	if others == 0 {
		return ErrLastUser
	}
	// The id keys the cascade — the credentials and ledger rows carry
	// user_id, not username.
	var id int64
	if err := tx.QueryRowContext(ctx,
		`SELECT id FROM users WHERE username = ?`, name).Scan(&id); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return fmt.Errorf("identity: unknown user: %w", err)
		}
		return fmt.Errorf("identity: delete user id: %w", err)
	}
	// The cascade joins the guard + delete in this one tx (3.5): the
	// user's session credentials, both ledger slots, and group membership
	// die with the user row itself.
	for _, q := range []string{
		`DELETE FROM credentials WHERE user_id = ? AND kind = 'session'`,
		`DELETE FROM playback_progress WHERE user_id = ?`,
		`DELETE FROM watched_items WHERE user_id = ?`,
		`DELETE FROM group_members WHERE user_id = ?`,
	} {
		if _, err := tx.ExecContext(ctx, q, id); err != nil {
			return fmt.Errorf("identity: delete user cascade: %w", err)
		}
	}
	res, err := tx.ExecContext(ctx, `DELETE FROM users WHERE username = ?`, name)
	if err != nil {
		return fmt.Errorf("identity: delete user %q: %w", name, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("identity: delete user affected: %w", err)
	}
	if n == 0 {
		return fmt.Errorf("identity: unknown user: %w", sql.ErrNoRows)
	}
	return tx.Commit()
}

// execOne runs one single-row UPDATE and maps an empty effect to the
// wrapped sql.ErrNoRows unknown-user convention.
func (s *Service) execOne(ctx context.Context, what, q string, args ...any) error {
	res, err := s.st.DB().ExecContext(ctx, q, args...)
	if err != nil {
		return fmt.Errorf("%s: %w", what, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("%s affected: %w", what, err)
	}
	if n == 0 {
		return fmt.Errorf("%s: unknown user: %w", what, sql.ErrNoRows)
	}
	return nil
}
